import{_ as r,o,c as e,a5 as s}from"./chunks/framework.DJo0M80U.js";const c=JSON.parse('{"title":"Pinia “放外面 vs. 放里面” 决策全攻略","description":"\\\\ 以注册弹窗组件 ( registerModal ) 为例，讲透 模块作用域 和 Store 内 两种写法的利弊、适用场景与实现细节。 Pinia 弹窗注册两种写法关键代码 1. 模块作用域（放外面） // src/stores/modalManager.ts import \\\\。","frontmatter":{"title":"Pinia “放外面 vs. 放里面” 决策全攻略","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","路由与状态管理"],"description":"\\\\ 以注册弹窗组件 ( registerModal ) 为例，讲透 模块作用域 和 Store 内 两种写法的利弊、适用场景与实现细节。 Pinia 弹窗注册两种写法关键代码 1. 模块作用域（放外面） // src/stores/modalManager.ts import \\\\。","sidebarWeight":2,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/pinia/Pinia “放外面 vs. 放里面” 决策全攻略.md"},"headers":[],"relativePath":"posts/Vue系统教程/04-路由与状态管理/Pinia “放外面 vs. 放里面” 决策全攻略.md","filePath":"posts/Vue系统教程/04-路由与状态管理/Pinia “放外面 vs. 放里面” 决策全攻略.md"}'),a={name:"posts/Vue系统教程/04-路由与状态管理/Pinia “放外面 vs. 放里面” 决策全攻略.md"};function n(d,t,i,g,l,p){return o(),e("div",null,[...t[0]||(t[0]=[s('<div><h1 id="pinia-放外面-vs-放里面-决策全攻略" tabindex="-1">Pinia “放外面 vs. 放里面” 决策全攻略 <a class="header-anchor" href="#pinia-放外面-vs-放里面-决策全攻略" aria-label="Permalink to &quot;Pinia “放外面 vs. 放里面” 决策全攻略&quot;">​</a></h1><blockquote><p>本节目标：理解“Pinia “放外面 vs. 放里面” 决策全攻略”的核心思路，并能把它用于实际开发或面试表达。 &gt; 以注册弹窗组件 (<code>registerModal</code>) 为例，讲透 <strong><strong>模块作用域</strong></strong> 和 <strong><strong>Store 内</strong></strong> 两种写法的利弊、适用场景与实现细节。</p></blockquote><h1 id="pinia-弹窗注册两种写法关键代码" tabindex="-1">Pinia 弹窗注册两种写法关键代码 <a class="header-anchor" href="#pinia-弹窗注册两种写法关键代码" aria-label="Permalink to &quot;Pinia 弹窗注册两种写法关键代码&quot;">​</a></h1><h2 id="_1-模块作用域-放外面" tabindex="-1">1. 模块作用域（放外面） <a class="header-anchor" href="#_1-模块作用域-放外面" aria-label="Permalink to &quot;1. 模块作用域（放外面）&quot;">​</a></h2><p>// src/stores/modalManager.ts import { markRaw } from &#39;vue&#39; // 注册表 —— 模块级单例 const registry: Record&lt;string, any&gt; = {} /** 在业务模块里调用，注册自己的弹窗组件（幂等） <em>/ export function registerModal(type: string, comp: any) { if (!registry[type]) registry[type] = markRaw(comp) } /</em>* ModalHost 渲染时按 type 取组件 */ export function getModalComp(type: string) { return registry[type] }</p><h2 id="_2-store-内部-放里面" tabindex="-1">2. Store 内部（放里面） <a class="header-anchor" href="#_2-store-内部-放里面" aria-label="Permalink to &quot;2. Store 内部（放里面）&quot;">​</a></h2><p>// src/stores/modalManager.ts import { defineStore } from &#39;pinia&#39; import { markRaw } from &#39;vue&#39; export const useModalManagerStore = defineStore(&#39;modal&#39;, () =&gt; { // 非响应式注册表，避免被 Devtools 追踪 / 序列化 const registry = markRaw&lt;Record&lt;string, any&gt;&gt;({}) /** 在业务模块里调用，注册自己的弹窗组件（幂等） <em>/ function registerModal(type: string, comp: any) { if (!registry[type]) registry[type] = comp } /</em>* ModalHost 渲染时按 type 取组件 */ function getModalComp(type: string) { return registry[type] } return { // 其它 open / close API ... registerModal, getModalComp, } })</p><h3 id="_2-评估维度-对比表" tabindex="-1">2. 评估维度 &amp; 对比表 <a class="header-anchor" href="#_2-评估维度-对比表" aria-label="Permalink to &quot;2. 评估维度 &amp; 对比表&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>维度</strong></td><td><strong>放 外面（模块级）</strong></td><td><strong>放 里面（Store 级）</strong></td></tr><tr><td><strong>生命周期</strong></td><td>只要文件被一次 import 就存在；与 Pinia 无关</td><td>必须先 useStore()，才会创建实例</td></tr><tr><td><strong>响应式 / 序列化</strong></td><td>纯普通对象，不被 Vue Proxy 追踪；无需 state</td><td>默认非响应式（放函数作用域），安全；若误放进 state 会被 Proxy &amp; Devtools 追踪，可能报序列化警告</td></tr><tr><td><strong>注册时机</strong></td><td><strong>任意时机</strong>：可在根实例创建前注册</td><td>只能在 Pinia 安装后、组件 setup() 内或之后注册</td></tr><tr><td><strong>循环依赖风险</strong></td><td>小（只是简单工具函数）</td><td>store 内 import 同业务组件，容易出现循环引用</td></tr><tr><td><strong>懒加载能力</strong></td><td>import() 组件 → 自然分包</td><td>若静态 import 组件，跟 store 打进同一 chunk；需 defineAsyncComponent 才能拆包</td></tr><tr><td><strong>IDE 补全</strong></td><td>registerModal() 需手动 import</td><td>所有 API 都挂在 store，modalStore.registerModal() 补全友好</td></tr><tr><td><strong>单元测试</strong></td><td>直接调用函数即可，不必 mock Pinia</td><td>需创建 Pinia 容器、拿 store</td></tr><tr><td><strong>团队规范</strong></td><td>偏向“工具”风格，store 更干净</td><td>所有相关 API 收敛一处，易查找</td></tr></tbody></table><h3 id="_3-决策指南" tabindex="-1">3. 决策指南 <a class="header-anchor" href="#_3-决策指南" aria-label="Permalink to &quot;3. 决策指南&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>场景问题</strong></td><td><strong>建议</strong></td></tr><tr><td><strong>注册操作要在 Pinia 初始化之前执行吗？</strong>（如入口脚本、插件注入）</td><td><strong>放外面</strong></td></tr><tr><td><strong>需要按路由懒加载（首屏包最小化）吗？</strong></td><td>两者都可，</td></tr><tr><td>但放外面 + import() 更自然</td><td></td></tr><tr><td><strong>团队规定“所有状态/API 都集中到 store”吗？</strong></td><td><strong>放里面</strong>，但 registry 必须 markRaw 且别放 state</td></tr><tr><td><strong>业务组件数量多，担心循环依赖？</strong></td><td><strong>放外面</strong> 可降低循环引用概率</td></tr><tr><td><strong>更重视 IDE 补全 vs. 灵活注册时机？</strong></td><td>补全：<strong>放里面</strong>；</td></tr><tr><td>灵活：<strong>放外面</strong></td><td></td></tr></tbody></table><h3 id="_4-实现要点-细节坑" tabindex="-1">4. 实现要点 &amp; 细节坑 <a class="header-anchor" href="#_4-实现要点-细节坑" aria-label="Permalink to &quot;4. 实现要点 &amp; 细节坑&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>要点</strong></td><td><strong>放外面的写法</strong></td><td><strong>放里面的写法</strong></td></tr><tr><td><strong>幂等注册</strong></td><td>模块作用域天然单例；只需 if (!registry[type])</td><td>可能会热更新多次调用 useStore() → 建 installed 标记或在模块作用域注册</td></tr><tr><td><strong>markRaw</strong></td><td>建议（非必须）</td><td><strong>必须</strong>，否则 Vue Proxy 会包裹组件对象</td></tr><tr><td><strong>类型文件</strong></td><td>可以写 `export type ModalType = &#39;openOrder&#39;</td><td>&#39;alert&#39;` 用于校验</td></tr><tr><td><strong>测试</strong></td><td>registerModal(&#39;x&#39;, Dummy) 即可</td><td>需 createPinia() + setActivePinia()</td></tr></tbody></table><h3 id="_5-两种写法的混搭策略-大厂通用" tabindex="-1">5. 两种写法的混搭策略（大厂通用） <a class="header-anchor" href="#_5-两种写法的混搭策略-大厂通用" aria-label="Permalink to &quot;5. 两种写法的混搭策略（大厂通用）&quot;">​</a></h3><ol><li><strong><strong>公共/基础弹窗</strong></strong><ul><li>静态注册在 <code>modalManager</code> 顶部（放外面），保证任何页面随时可用。</li></ul></li><li><strong><strong>仅业务域使用的弹窗</strong></strong><ul><li>在业务页面或 <code>registerModals.ts</code> 内调用 <code>registerModal</code>（外部写法即可）； 或封装成 <code>store.registerModal()</code>（内部写法）。</li></ul></li><li><strong><strong>统一调用</strong></strong><ul><li>页面只需 <code>await modalStore.open(type, payload)</code>，对注册位置无感知。</li></ul></li></ol><h3 id="_6-代码示例-同时支持两种注册方式" tabindex="-1">6. 代码示例：同时支持两种注册方式 <a class="header-anchor" href="#_6-代码示例-同时支持两种注册方式" aria-label="Permalink to &quot;6. 代码示例：同时支持两种注册方式&quot;">​</a></h3><p>/* modalManager.ts <em>/ import { defineStore } from &#39;pinia&#39; import { markRaw } from &#39;vue&#39; const registry: Record&lt;string, any&gt; = {} export function registerModal(type: string, comp: any) { if (!registry[type]) registry[type] = markRaw(comp) } export function getModalComp(type: string) { return registry[type] } export const useModalManagerStore = defineStore(&#39;modal&#39;, () =&gt; { /</em> --- 弹窗栈逻辑省略，与前述一致 --- <em>/ /</em> 也暴露同名 API，内部只是代理外部函数 */ function register(type: string, comp: any) { registerModal(type, comp) } return { modals, open, _close, register, getModalComp } })</p><p>&gt; - <strong><strong>想在页面顶层注册</strong></strong>： &gt; import { registerModal } from &#39;@/stores/modalManager&#39; &gt; registerModal(&#39;openOrder&#39;, Comp) &gt; &gt; - <strong><strong>想在组件</strong> <strong><code>setup</code></strong> <strong>内注册</strong></strong>： &gt; const modal = useModalManagerStore() &gt; modal.register(&#39;openOrder&#39;, Comp)</p><h2 id="✨-结论" tabindex="-1">** <strong>✨</strong> **结论 <a class="header-anchor" href="#✨-结论" aria-label="Permalink to &quot;** **✨** **结论&quot;">​</a></h2><ul><li><strong><strong>无绝对优劣</strong></strong>：外部更灵活、性能友好；内部更集中、IDE 友好。</li><li><strong><strong>实践建议</strong></strong>： <ol><li><strong><strong>Registry 放外部</strong></strong>作为默认；</li><li>如团队风格要求，也可在 store 再包一层代理方法，兼顾两种调用习惯；</li><li>别把组件对象放 <code>state</code>，务必 <code>markRaw</code>，避免序列化 / Proxy 开销。</li></ol></li></ul></div>',1)])])}const h=r(a,[["render",n]]);export{c as __pageData,h as default};
